  /**
   * Second-direction distance (asymmetric two-sided).
   * @unit mm
   * @minimum 0
   */
  distance2?: number;
  /**
   * Draft angle in radians (0 = none).
   * @unit rad
   */
  draftAngle?: number;
  /** "Through all": extrude far enough to span every existing body (both ways). */
  through?: boolean;
  /** "Up to face": extrude until the profile reaches this target face's plane. */
  upToFace?: TopoTarget;
  /**
   * How the solid combines with the bodies before it.
   * @default "new"
   */
  operation?: BooleanMode;
  id: string;
  name: string;
