/**
 * A subdivision-surface body (Catmull-Clark). Authored in the **sculpt** mode as an editable control cage — a quad mesh you push/pull/subdivide — and committed into the document as a body. The cage is stored verbatim (control points + quad faces); the surface is computed by subdividing `level` times (pure TS subdivision in `cad/model/subdiv.ts`), then meshed for display. Independent of the OCC kernel (which has no native subdivision), so it works everywhere.
 */
export type SubdivBodyFeature = {
  type: "subdivBody";
  /** Control-cage vertices (object space, mm). */
  controlPoints: Vec3[];
  /** Quad (or tri) faces as indices into controlPoints. */
  faces: number[][];
  /** Catmull-Clark subdivision iterations (0 = the raw cage). */
  level: number;
  /** How the resulting solid combines with existing bodies (default "new"). */
  operation?: BooleanMode;
  id: string;
  name: string;
  suppressed?: boolean;
  /** Populated by rebuild when this feature fails. */
  error?: string;
  /**
   * THE BODY-STATE EDGE — the explicit form of what a timeline used to supply implicitly as "whatever came before".
   */
  consumes?: string[];
  /**
   * DECLARED BY A CODE PART — set only in memory, on a feature a CodeFeature's file declared when the part was opened (`app-3d-design` `model/code-parts.ts`). It holds the code feature as it is stored; a save writes that back in place of every feature it declared, so nothing a file declares is ever written.
   */
  declaredBy?: CodeFeature;
};

/**
 * WHO SELLS A PART, AND ON WHAT TERMS: one supplier's offer (docs/formats.md § logistics). The quantity terms (`stock`, `moq`, `orderMultiple`, `leadTimeDays`, `priceBreaks`) are the ones a component catalog's offer states. A price or a stock says where and when it was read (`source`, `date`).
 */
export type SupplierOffer = {
  /** The supplier: a distributor, a shop, a fab house ("LCSC", "DigiKey", "JLCPCB"). */
  name: string;
  /** The supplier's own number for the part (its SKU). */
  sku?: string;
  /** The page that sells it. */
  url?: string;
  /** ISO 4217 currency code of the prices. */
  currency?: string;
  /** The unit price from each quantity up; below the smallest there is no price. */
  priceBreaks?: PriceBreak[];
  /**
   * The smallest order.
   * @minimum 1
   */
  moq?: number;
  /**
   * An order is a multiple of this (a reel, a tray).
   * @minimum 1
   */
  orderMultiple?: number;
  /**
   * Days from order to shipment.
   * @minimum 0
   */
  leadTimeDays?: number;
  /**
   * Units the supplier says it has.
   * @minimum 0
   */
  stock?: number;
  /** Where the terms were read: a page, a quote, or "estimate" with its basis. */
  source?: string;
  /** The day the terms were read, YYYY-MM-DD. */
  date?: string;
};

