/** A box in model coordinates, by two opposite corners. */
export type TopoBox = {
  /**
   * The least corner.
   * @unit mm
   */
  min: Vec3;
  /**
   * The greatest corner.
   * @unit mm
   */
  max: Vec3;
};

/**
 * WHAT FACES OR EDGES ARE, STATED AS DATA — the tests one face or edge of the bodies must pass to be chosen.
 */
export type TopoQuery = {
  /** Faces: flat, facing this direction (its outward normal, same sense). */
  normal?: Vec3;
  /** Edges: straight, along this direction (either sense). */
  parallel?: Vec3;
  /** Edges: straight, at right angles to this direction. */
  perpendicular?: Vec3;
  /**
   * Faces: a cylinder, cone or torus about an axis in this direction. Edges: a circle or arc about one. Either sense.
   */
  axis?: Vec3;
  /** The kind of surface (a face) or curve (an edge). */
  geometry?: "line" | "circle" | "arc" | "ellipse" | "spline" | "other" | "plane" | "cylinder" | "cone" | "sphere" | "torus";
  /**
   * Edges: the length.
   * @unit mm
   */
  length?: TopoRange;
  /**
   * Faces: the radius of a cylinder or sphere. Edges: the radius of a circle or arc.
   * @unit mm
   */
  radius?: TopoRange;
  /** Faces: the area, in square millimetres. */
  area?: TopoRange;
  /** Edges: the edges that bound a face this face query chooses ("the edges of the top face"). */
  ofFace?: TopoQuery;
  /**
   * Made by this feature: a face that lies on the bodies after the feature ran and not on the bodies before it, and an edge that bounds such a face. A hole's wall and its rim are made by the hole; the face it was drilled in is not.
   */
  createdBy?: string;
  /**
   * Its centre (a face's centroid, an edge's midpoint) lies in this box, in model coordinates.
   * @unit mm
   */
  inBox?: TopoBox;
  /**
   * Of what passes every other test, only the ones whose centre is farthest along this direction ("the top").
   */
  farthest?: Vec3;
  /**
   * One of these holds.
   * @minItems 1
   */
  any?: TopoQuery[];
  /** This does not hold. */
  not?: TopoQuery;
};

/** A range of a measured value. An end left out is open. */
export type TopoRange = {
  /** At least this. */
  min?: number;
  /** At most this. */
  max?: number;
};

export type TopoRef = {
  /** The feature whose result body contains this sub-shape (optional hint). */
  feature?: string;
  kind: "face" | "edge" | "vertex";
  signature: TopoSignature;
  /** Human label, e.g. "Top face of Extrude1". */
  label?: string;
};

/**
 * Faces or edges chosen by a TopoQuery when the feature is built: "every vertical edge", "the edges of the top face", "the rims the hole made". Beside the pick (TopoRef), which names one by where it was.
 */
export type TopoSelector = {
  kind: "face" | "edge";
  /** What they are. */
  select: TopoQuery;
  /** Human label, e.g. "Vertical edges". */
  label?: string;
};

export type TopoSignature = {
  /** Face center, edge midpoint, or vertex position. */
  point: Vec3;
  /** Face normal (faces only). */
  normal?: Vec3;
  /** Face area (faces only). */
  area?: number;
  /** Edge length (edges only). */
  length?: number;
  /** Edge chord direction, normalized (edges only). */
  dir?: Vec3;
};

/**
 * What a feature takes where it needs faces or edges: one picked (TopoRef) or the ones a query chooses.
 */
export type TopoTarget = TopoRef | TopoSelector;

/**
 * A torus: `S(u,v) = origin + (Rmaj + Rmin·cos v)(cos u·x + sin u·y) + Rmin·sin v·axis`. K = cos v / (Rmin(Rmaj + Rmin·cos v)) — it CHANGES SIGN across the tube, which makes it the sharpest doubly-curved control: no single scalar can describe its distortion.
 */
export type ToroidalSurface = {
  kind: "torus";
  majorRadius: number;
  minorRadius: number;
  origin: Vec3;
  xAxis: Vec3;
  yAxis: Vec3;
  axis: Vec3;
};

export type TransformFeature = {
  type: "transform";
  /** The feature whose bodies move. */
  seedFeature: string;
  /**
   * How far they move.
   * @unit mm
   */
  translate?: Vec3;
  /** The axis they turn about. */
  rotateAxis?: AxisRef;
  /**
   * How far they turn about it.
   * @unit rad
   */
  rotateAngle?: number;
  id: string;
  name: string;
  suppressed?: boolean;
  /** Populated by rebuild when this feature fails. */
  error?: string;
  /**
   * THE BODY-STATE EDGE — the explicit form of what a timeline used to supply implicitly as "whatever came before".
   */
  consumes?: string[];
  /**
   * DECLARED BY A CODE PART — set only in memory, on a feature a CodeFeature's file declared when the part was opened (`app-3d-design` `model/code-parts.ts`). It holds the code feature as it is stored; a save writes that back in place of every feature it declared, so nothing a file declares is ever written.
   */
  declaredBy?: CodeFeature;
};

export type UnfoldFeature = {
  type: "unfold";
  /**
   * K-factor for bend-allowance (neutral-fibre) computation; default 0.44.
   * @minimum 0
   * @maximum 1
   * @default 0.44
   */
  kFactor?: number;
  id: string;
  name: string;
  suppressed?: boolean;
  /** Populated by rebuild when this feature fails. */
  error?: string;
  /**
   * THE BODY-STATE EDGE — the explicit form of what a timeline used to supply implicitly as "whatever came before".
   */
  consumes?: string[];
  /**
   * DECLARED BY A CODE PART — set only in memory, on a feature a CodeFeature's file declared when the part was opened (`app-3d-design` `model/code-parts.ts`). It holds the code feature as it is stored; a save writes that back in place of every feature it declared, so nothing a file declares is ever written.
   */
  declaredBy?: CodeFeature;
};

export type UnwrapChart = {
  id: string;
  /** The b-rep face this patch was taken from — a real dependency edge, exactly like every other ref. */
  source?: TopoRef;
  surface: UnwrapSurface;
  rect: ParamRect;
  /** Filled in by `buildUnwrapDomain` from the declared identifications; never authored by hand. */
  placement?: ChartPlacement;
  /**
   * A fitted flattening, replacing the closed form for this chart. Absent ⇒ the analytic map below, which is an ISOMETRY wherever the surface is developable.
   */
  map?: FittedChartMap;
};

export type UnwrapDomain = {
  id: string;
  /** Charts with their placements resolved. */
  charts: UnwrapChart[];
  /** THE CHART THE ATLAS IS MEASURED FROM — the declared anchor the layout started at. */
  anchor: string;
  /** The identifications that PLACED a chart — adjacent on the part AND adjacent in the flat domain. */
  stitches: UnwrapIdentification[];
  /** The identifications the layout could not use: a cut in 2D that is NOT a cut in 3D. */
  seams: UnwrapIdentification[];
  /** Proved, not copied from the spec. */
  isometric: boolean;
  developability: DevelopabilityVerdict[];
  /** The distortion each chart's map applies, as EXTREMES. */
  distortion: ChartDistortionSummary[];
  /**
   * Every FITTED chart's residual against the flattening it was fitted to, in millimetres, and the bound it was admitted under. Empty on an atlas whose charts are all closed-form.
   */
  fits: {
    chart: string;
    residual: number;
    tolerance: number;
  }[];
  bindTolerance: number;
  resolution: number;
};

/** "These two chart edges are the same curve on the part." The atlas's only authored relation. */
export type UnwrapIdentification = {
  id: string;
  a: {
    chart: string;
    edge: ChartEdge;
  };
  b: {
    chart: string;
    edge: ChartEdge;
  };
  /** Human label for the panel — "top face ↔ fillet", "cylinder seam". */
  label?: string;
};

export type UnwrapSurface = PlanarSurface | CylindricalSurface | ConicalSurface | SphericalSurface | ToroidalSurface;

/**
 * A point or vector in 2D (sketch space).
 * @minItems 2
 * @maxItems 2
 */
export type Vec2 = [number, number];

/**
 * A point or vector in 3D.
 * @minItems 3
 * @maxItems 3
 */
export type Vec3 = [number, number, number];

/**
 * A point or vector in 3D.
 * @minItems 3
 * @maxItems 3
 */
export type Vec32 = [number, number, number];

/**
 * A **scalar/label voxel volume** — CT/MRI/microscopy/segmentation grids (NIfTI/NRRD/DICOM). The field is normalized 0..1 and downsampled to a display-friendly grid on import (large clinical volumes don't fit a JSON doc verbatim). Rendered as three orthogonal MPR slice planes or a marching-cubes isosurface.
 */
